-- Preserve the original Grade 7 Mathematics source row and its competency IDs from migration 003.
update public.source_documents
set source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20Mathematics%20CG%202023%20Grades%201-10.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides'
where source_url = 'https://www.deped.gov.ph/wp-content/uploads/MATATAG-Mathematics-CG-Grades1-4-and-7.pdf'
  and not exists (select 1 from public.source_documents where source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20Mathematics%20CG%202023%20Grades%201-10.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides');

update public.curriculum_domains cd
set name = 'Measurement and Geometry (MG)', code = 'D01', sort_order = 1
from public.curriculum_subjects cs
join public.curriculum_versions cv on cv.id = cs.curriculum_version_id
where cd.subject_id = cs.id
  and cv.code = 'REVISED-K10-MATATAG'
  and cs.grade_level = 'Grade 7'
  and cs.name = 'Mathematics'
  and cd.name = 'Measurement and Geometry'
  and not exists (select 1 from public.curriculum_domains existing where existing.subject_id = cs.id and existing.name = 'Measurement and Geometry (MG)');

update public.curriculum_domains cd
set name = 'Number and Algebra (NA)', code = 'D02', sort_order = 2
from public.curriculum_subjects cs
join public.curriculum_versions cv on cv.id = cs.curriculum_version_id
where cd.subject_id = cs.id
  and cv.code = 'REVISED-K10-MATATAG'
  and cs.grade_level = 'Grade 7'
  and cs.name = 'Mathematics'
  and cd.name = 'Number and Algebra'
  and not exists (select 1 from public.curriculum_domains existing where existing.subject_id = cs.id and existing.name = 'Number and Algebra (NA)');

update public.curriculum_domains cd
set name = 'Data and Probability (DP)', code = 'D03', sort_order = 3
from public.curriculum_subjects cs
join public.curriculum_versions cv on cv.id = cs.curriculum_version_id
where cd.subject_id = cs.id
  and cv.code = 'REVISED-K10-MATATAG'
  and cs.grade_level = 'Grade 7'
  and cs.name = 'Mathematics'
  and cd.name = 'Data and Probability'
  and not exists (select 1 from public.curriculum_domains existing where existing.subject_id = cs.id and existing.name = 'Data and Probability (DP)');

