  and cs.grade_level = 'Grade 1'
  and cs.name = 'GMRC'
  and cc.subject_id = cs.id
  and cc.academic_period_id = ap.id
  and cc.source_document_id = sd.id
  and cc.sort_order = 6;

insert into public.curriculum_competencies (subject_id, domain_id, academic_period_id, competency_code, competency_text, sort_order, source_document_id, source_page, verification_status)
select cs.id, cd.id, ap.id, null, 'Naipakikita ang pagmamahal sa bayan sa pamamagitan ng palagiang pagsunod sa mga panuntunan para sa mga sagisag ng bayan a. Nakakikilala sa halaga ng watawat bilang pangunahing sagisag ng bayan b. Naiuugnay na ang watawat bilang pangunahing sagisag ng bayan ay bahagi ng mga pambansang paniniwala, tradisyon, at pagpapahalaga c. Nailalapat ang mga angkop na kilos sa pagkilala ng watawat bilang pangunahing sagisag ng bayan', 6, sd.id, 55, 'verified'
from public.curriculum_subjects cs
join public.curriculum_versions cv on cv.id = cs.curriculum_version_id
join public.curriculum_domains cd on cd.subject_id = cs.id and cd.code = 'D24'
join public.academic_periods ap on ap.subject_id = cs.id and ap.sequence = 4
join public.source_documents sd on sd.source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20GMRC%20and%20VE%20CG%202023%20Grades%201-10.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides'
where cv.code = 'REVISED-K10-MATATAG' and cs.grade_level = 'Grade 1' and cs.name = 'GMRC'
  and not exists (
    select 1 from public.curriculum_competencies cc
    where cc.subject_id = cs.id
      and cc.academic_period_id = ap.id
      and cc.source_document_id = sd.id
      and cc.sort_order = 6
  );

delete from public.curriculum_competencies cc
using public.curriculum_subjects cs, public.curriculum_versions cv, public.academic_periods ap, public.source_documents sd
where cs.curriculum_version_id = cv.id
  and ap.subject_id = cs.id
  and sd.source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20GMRC%20and%20VE%20CG%202023%20Grades%201-10.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides'
  and cv.code = 'REVISED-K10-MATATAG'
  and cs.grade_level = 'Grade 1'
  and cs.name = 'GMRC'
  and cc.subject_id = cs.id
  and cc.academic_period_id = ap.id
  and cc.source_document_id = sd.id
  and not ((ap.sequence = 1 and cc.sort_order in (1, 2, 3, 4, 5, 6)) or (ap.sequence = 2 and cc.sort_order in (1, 2, 3, 4, 5, 6)) or (ap.sequence = 3 and cc.sort_order in (1, 2, 3, 4, 5, 6)) or (ap.sequence = 4 and cc.sort_order in (1, 2, 3, 4, 5, 6)));

