update public.curriculum_competencies cc
set domain_id = cd.id,
  competency_code = 'EN10LIT-I-1',
  competency_text = 'Analyze literary texts as expressions of individual or communal values within: a conflict character vs. character character vs. society character vs. nature/environment character vs. self b character c characterization e spectacle, dialogue, and music f rhyme and meter g diction h tone and mood i style j patterns and motifs k figures of speech and sound devices l point of view and narrative techniques m organic unity n sign and referent o binary opposition a deictic speaker/narrator and place speaker/narrator and situation b co-text c collocation',
  source_page = 175,
  verification_status = 'verified',
  updated_at = timezone('utc', now())
from public.curriculum_subjects cs
join public.curriculum_versions cv on cv.id = cs.curriculum_version_id
join public.curriculum_domains cd on cd.subject_id = cs.id and cd.code = 'D01'
join public.academic_periods ap on ap.subject_id = cs.id and ap.sequence = 1
join public.source_documents sd on sd.source_url = 'https://depedph-my.sharepoint.com/personal/ouct_deped_gov_ph/_layouts/15/onedrive.aspx?id=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides%2FFINAL%20MATATAG%20English%20CG%202023%20Grades%202-10%20%28withAppendices%29.pdf&parent=%2Fpersonal%2Fouct_deped_gov_ph%2FDocuments%2FMATATAG%20Curriculum%20Guides'
where cv.code = 'REVISED-K10-MATATAG'
  and cs.grade_level = 'Grade 10'
  and cs.name = 'English'
  and cc.subject_id = cs.id
  and cc.academic_period_id = ap.id
  and cc.source_document_id = sd.id
  and cc.sort_order = 1;

